def edit(path, subs):
    s = open(path).read()
    for label, old, new, want in subs:
        c = s.count(old)
        if c != want: E.append((path.split('/')[-1], label, c, want)); continue
        s = s.replace(old, new); print('  ok', path.split('.')[-1], label, c)
    return s
